// BOOKPORT 20 BETA — АННА / ВОДА
// Словарь: все 480 исходных вариантов сохранены и расширены.
// Категории и пороги выбирает waterCoaching.ts, а не этот файл.
// pct: timePct для текущего дня, суточный pct для истории; поэтому тексты
// называют его «расчётным ориентиром», а не универсальной нормой гидратации.
// Данные замеров, симптомов и вчерашней клетчатки не устанавливают причинность.
// Активные варианты различают текущий и исторический день через WaterContext.

export interface WaterContext {
  userName: string;
  dayIndex?: number;
  // Дополнительные поля для точного объяснения суточной цели и темпа.
  // Движок передаёт цель, дневной процент и отдельный процент текущего темпа.
  isToday?: boolean;
  goal?: number;
  dailyPct?: number;
  expectedGoalOnNow?: number | null;
  latestSymptoms?: string[];
  latestComfort?: 'easy' | 'normal' | 'hard' | null;
  userGender?: 'male' | 'female';
  waterStatus: 'zero' | 'deficit' | 'optimum' | 'excess';
  pct: number;
  amount: number;
  latestBristol: number | null;
  yesterdayFiber: number;
  latestMeasurements?: {
    pulseAvg: number | null;
    systolic: number | null;
    diastolic: number | null;
    weightAvg: number | null;
    weightDelta: number | null;
    tonus: 'low' | 'normal' | 'high' | 'no_data';
  };
}

const recordedPressure = (ctx: WaterContext): string => {
  const sys = ctx.latestMeasurements?.systolic;
  const dia = ctx.latestMeasurements?.diastolic;
  if (sys != null && dia != null) return `${sys}/${dia} мм рт. ст.`;
  if (sys != null) return `систолическое ${sys} мм рт. ст.`;
  if (dia != null) return `диастолическое ${dia} мм рт. ст.`;
  return 'без указанного числового значения';
};

const renderPhrase = (phrase: string, ctx: WaterContext): string => {
  const amount = Math.round(ctx.amount);
  const goal = ctx.goal;
  const dailyPct = ctx.dailyPct;
  const expected = ctx.expectedGoalOnNow;
  const waterProgress = goal != null && goal > 0 && dailyPct != null
    ? ctx.isToday === true && expected != null && expected > 0
      ? `Записано ${amount} мл из ${Math.round(goal)} мл за день (${Math.round(dailyPct)}%). К этому часу по графику ожидалось ${Math.round(expected)} мл: ${amount >= expected ? `опережение на ${Math.round(amount - expected)} мл` : `отставание на ${Math.round(expected - amount)} мл`} (${Math.round(ctx.pct)}% промежуточного ориентира).`
      : `За выбранный день записано ${amount} мл из ${Math.round(goal)} мл (${Math.round(dailyPct)}% дневной цели).`
    : `По записям за выбранный день учтено ${amount} мл воды.`;
  const paceDecision = ctx.isToday === true && dailyPct != null
    ? dailyPct >= 100
      ? 'Дневная цель уже достигнута; дополнительная вода ради процента не требуется.'
      : 'К этому времени темп достаточен, хотя дневная цель ещё впереди.'
    : ctx.isToday === false
      ? 'Это итог выбранного дня, а не оценка текущего часа.'
      : 'Выбирай дальнейший режим с учётом самочувствия и личных ограничений.';
  const values: Record<string, string> = {
    waterProgress,
    paceDecision,
    name: ctx.userName,
    amount: String(Math.round(ctx.amount)),
    pct: String(Math.round(ctx.pct)),
    bristol: ctx.latestBristol == null ? 'не указан' : String(ctx.latestBristol),
    fiber: String(ctx.yesterdayFiber),
    pulse: ctx.latestMeasurements?.pulseAvg == null ? 'не указан' : String(ctx.latestMeasurements.pulseAvg),
    bp: recordedPressure(ctx),
    weightDelta: ctx.latestMeasurements?.weightDelta == null ? 'не указана' : String(ctx.latestMeasurements.weightDelta),
    weightLossAbs: ctx.latestMeasurements?.weightDelta == null
      ? 'не указано'
      : String(Math.abs(ctx.latestMeasurements.weightDelta)),
  };
  return phrase.replace(/\{(waterProgress|paceDecision|name|amount|pct|bristol|fiber|pulse|bp|weightDelta|weightLossAbs)\}/g,
    (_, key: string) => values[key]);
};

// Имя функции сохранено для совместимости с движком. В каждой категории
// исходный массив остаётся нетронутым, новые проверенные варианты добавлены в конец.

export const getRandomPhrase = (phrases: string[], ctx: WaterContext): string => {
  if (!phrases?.length) return '';
  // Один Bristol 3–5 ещё не подтверждает отсутствия симптомов и дискомфорта.
  if (phrases === cross_digestion_ideal &&
      (ctx.latestSymptoms === undefined || ctx.latestSymptoms.length > 0 ||
       ctx.latestComfort === undefined || ctx.latestComfort === 'hard')) return '';
  const candidates = phrases.slice(-20); // 20 новых смысловых вариантов для каждой категории.
  if (!candidates.length) return '';
  const seed = `${phrases[0]}|${ctx.dayIndex ?? ''}|${ctx.amount}|${ctx.pct}|${ctx.waterStatus}`;
  let hash = 2166136261;
  for (let i = 0; i < seed.length; i += 1) {
    hash = Math.imul(hash ^ seed.charCodeAt(i), 16777619);
  }
  return renderPhrase(candidates[(hash >>> 0) % candidates.length], ctx);
};

